    return try!  FfiConverterString.lift(try! rustCall() {
    uniffi_pacific_ffi_fn_method_core_coarse_area(self.uniffiClonePointer(),
        FfiConverterDouble.lower(lat),
        FfiConverterDouble.lower(lon),
        FfiConverterUInt8.lower(precision),$0
