/**
 * One message in the STRUCTURED chat projection — the folded residue of real
 * forum.post/forum.react Deltas, not UI state. The UI binds bubbles, reaction
 * pills, reply quotes and the time-sent stamp to these fields directly (no
 * string parsing). A message is addressed by `(author, gen)`: `author` is the
 * author's 64-char identity hex and `gen` its Lamport generation — the same
 * `MsgRef` the core uses, so reacting/replying just echoes these two back.
 */
public struct ChatMsg {
    public var author: String
    public var gen: UInt64
    public var text: String
    public var ts: UInt64
    public var mine: Bool
    public var replyToAuthor: String
    public var replyToGen: UInt64
    public var replyPreview: String
    public var reactions: [ChatReaction]
    /**
     * WhatsApp-style delivery/read code, set only on OUR OWN messages (`mine`):
     * 0 = none (an incoming message), 1 = sent, 2 = delivered to every recipient,
     * 3 = read by every recipient. The UI renders ✓ / ✓✓ / ✓✓-blue from this.
     */
    public var receipt: UInt8
    /**
     * Live vote tallies (the Reddit half of a Forum post). The score the UI
     * shows is `up - down`, derived here and everywhere — never stored.
     */
    public var up: UInt32
    public var down: UInt32
    /**
     * THIS device's vote: 1 up, -1 down, 0 none — drives the arrows' lit state.
     */
    public var myVote: Int8

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(author: String, gen: UInt64, text: String, ts: UInt64, mine: Bool, replyToAuthor: String, replyToGen: UInt64, replyPreview: String, reactions: [ChatReaction], 
        /**
         * WhatsApp-style delivery/read code, set only on OUR OWN messages (`mine`):
         * 0 = none (an incoming message), 1 = sent, 2 = delivered to every recipient,
         * 3 = read by every recipient. The UI renders ✓ / ✓✓ / ✓✓-blue from this.
         */receipt: UInt8, 
        /**
         * Live vote tallies (the Reddit half of a Forum post). The score the UI
         * shows is `up - down`, derived here and everywhere — never stored.
         */up: UInt32, down: UInt32, 
        /**
         * THIS device's vote: 1 up, -1 down, 0 none — drives the arrows' lit state.
         */myVote: Int8) {
        self.author = author
        self.gen = gen
        self.text = text
        self.ts = ts
        self.mine = mine
        self.replyToAuthor = replyToAuthor
        self.replyToGen = replyToGen
        self.replyPreview = replyPreview
        self.reactions = reactions
        self.receipt = receipt
        self.up = up
        self.down = down
        self.myVote = myVote
    }
}



extension ChatMsg: Equatable, Hashable {
    public static func ==(lhs: ChatMsg, rhs: ChatMsg) -> Bool {
        if lhs.author != rhs.author {
            return false
        }
        if lhs.gen != rhs.gen {
            return false
        }
        if lhs.text != rhs.text {
            return false
        }
        if lhs.ts != rhs.ts {
            return false
        }
        if lhs.mine != rhs.mine {
            return false
        }
        if lhs.replyToAuthor != rhs.replyToAuthor {
            return false
        }
        if lhs.replyToGen != rhs.replyToGen {
            return false
        }
        if lhs.replyPreview != rhs.replyPreview {
            return false
        }
        if lhs.reactions != rhs.reactions {
            return false
        }
        if lhs.receipt != rhs.receipt {
            return false
        }
        if lhs.up != rhs.up {
            return false
        }
        if lhs.down != rhs.down {
            return false
        }
        if lhs.myVote != rhs.myVote {
            return false
        }
        return true
    }

