/**
 * One row of the hops-aware place listing: a Place I hold (`holder == ""`, hops 0)
 * or one a connection answered a discovery request with (`holder` = their identity
 * pk hex, hops 1|2). A remote row is a REFERENCE — enough to render and to adopt,
 * never the object itself.
 */
public struct DiscoveredRow {
    /**
     * Object id hex — local for a held row, the HOLDER's for a remote one.
     */
    public var id: String
    public var kind: String
    public var name: String
    public var descriptor: String
    /**
     * False when the row carries no point; `lat`/`lng` are meaningless then.
     */
    public var placed: Bool
    public var lat: Double
    public var lng: Double
    /**
     * "" = held locally; otherwise the holder's identity pk, hex.
     */
    public var holder: String
    /**
     * Handshakes between me and whoever holds it. 0 = mine.
     */
    public var hops: UInt32

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * Object id hex — local for a held row, the HOLDER's for a remote one.
         */id: String, kind: String, name: String, descriptor: String, 
        /**
         * False when the row carries no point; `lat`/`lng` are meaningless then.
         */placed: Bool, lat: Double, lng: Double, 
        /**
         * "" = held locally; otherwise the holder's identity pk, hex.
         */holder: String, 
        /**
         * Handshakes between me and whoever holds it. 0 = mine.
         */hops: UInt32) {
        self.id = id
        self.kind = kind
        self.name = name
        self.descriptor = descriptor
        self.placed = placed
        self.lat = lat
        self.lng = lng
        self.holder = holder
        self.hops = hops
    }
}



extension DiscoveredRow: Equatable, Hashable {
    public static func ==(lhs: DiscoveredRow, rhs: DiscoveredRow) -> Bool {
        if lhs.id != rhs.id {
            return false
        }
        if lhs.kind != rhs.kind {
            return false
        }
        if lhs.name != rhs.name {
            return false
        }
        if lhs.descriptor != rhs.descriptor {
            return false
        }
        if lhs.placed != rhs.placed {
            return false
        }
        if lhs.lat != rhs.lat {
            return false
        }
        if lhs.lng != rhs.lng {
            return false
        }
        if lhs.holder != rhs.holder {
            return false
        }
        if lhs.hops != rhs.hops {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(id)
        hasher.combine(kind)
        hasher.combine(name)
        hasher.combine(descriptor)
        hasher.combine(placed)
        hasher.combine(lat)
        hasher.combine(lng)
        hasher.combine(holder)
        hasher.combine(hops)
    }
}


