/**
 * One EVENT the EVENTS page binds to: the object id, when/where, and its ticket
 * listing folded to display shape. `listing` is the stable public listing key
 * (sha256(group_id ‖ owner) — what the box office and buyers reference, never the
 * group id). `sold`/`over_capacity` mirror the ledger fold.
 */
public struct EventRow {
    public var id: String
    public var title: String
    public var descriptor: String
    public var startMs: Int64
    /**
     * 0 = no stated end.
     */
    public var endMs: Int64
    public var venue: String
    /**
     * The venue as a Place GroupObject reference ("" = none) — the `happens_at`
     * edge the graph projector folds. `venue` above stays the flyer's free text.
     */
    public var venuePlace: String
    public var venuePlaceName: String
    public var venueAt: Int64
    public var placed: Bool
    public var lat: Double
    public var lng: Double
    /**
     * Whether a ticket listing exists at all.
     */
    public var listed: Bool
    public var priceCents: Int64
    public var currency: String
    public var capacity: Int64
    public var `open`: Bool
    public var sold: Int64
    public var overCapacity: Bool
    public var listing: String
    /**
     * The poster still, base64 ("" = none — the flyer-stripes placeholder state).
     * Full media (photos, clip) rides `event_media`, not the list row.
     */
    public var banner: String
    public var bannerMime: String
    public var photoCount: Int64
    public var hasClip: Bool
    /**
     * The lineup — artist names, billing order; empty = no lineup.
     */
    public var lineup: [String]
    /**
     * The RFC 5545 RRULE when this night repeats, canonicalised by the core on
     * write ("FREQ=WEEKLY;BYDAY=TH"); empty = it happens once.
     *
     * The rule crosses, NOT its occurrences. Expansion is relative to now and to
     * a window, so a stored next-occurrence would be stale the moment it was
     * written — the reader asks `recurrence_summary` / `recurrence_occurrences`
     * for what it needs, which are already here and already tested.
     */
    public var recurrence: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, title: String, descriptor: String, startMs: Int64, 
        /**
         * 0 = no stated end.
         */endMs: Int64, venue: String, 
        /**
         * The venue as a Place GroupObject reference ("" = none) — the `happens_at`
         * edge the graph projector folds. `venue` above stays the flyer's free text.
         */venuePlace: String, venuePlaceName: String, venueAt: Int64, placed: Bool, lat: Double, lng: Double, 
        /**
         * Whether a ticket listing exists at all.
         */listed: Bool, priceCents: Int64, currency: String, capacity: Int64, `open`: Bool, sold: Int64, overCapacity: Bool, listing: String, 
        /**
         * The poster still, base64 ("" = none — the flyer-stripes placeholder state).
         * Full media (photos, clip) rides `event_media`, not the list row.
         */banner: String, bannerMime: String, photoCount: Int64, hasClip: Bool, 
        /**
         * The lineup — artist names, billing order; empty = no lineup.
         */lineup: [String], 
        /**
         * The RFC 5545 RRULE when this night repeats, canonicalised by the core on
         * write ("FREQ=WEEKLY;BYDAY=TH"); empty = it happens once.
         *
         * The rule crosses, NOT its occurrences. Expansion is relative to now and to
         * a window, so a stored next-occurrence would be stale the moment it was
         * written — the reader asks `recurrence_summary` / `recurrence_occurrences`
         * for what it needs, which are already here and already tested.
         */recurrence: String) {
        self.id = id
        self.title = title
        self.descriptor = descriptor
        self.startMs = startMs
        self.endMs = endMs
        self.venue = venue
        self.venuePlace = venuePlace
        self.venuePlaceName = venuePlaceName
        self.venueAt = venueAt
        self.placed = placed
        self.lat = lat
        self.lng = lng
        self.listed = listed
        self.priceCents = priceCents
        self.currency = currency
        self.capacity = capacity
        self.`open` = `open`
        self.sold = sold
        self.overCapacity = overCapacity
        self.listing = listing
        self.banner = banner
        self.bannerMime = bannerMime
        self.photoCount = photoCount
        self.hasClip = hasClip
        self.lineup = lineup
        self.recurrence = recurrence
    }
}



