/**
 * One forum→host edge, the REVERSE of `group_forums`: which Group hosts this
 * room. The CHAT list joins on `forum` so a hosted room renders as
 * "Group / Room" instead of posing as a free-standing chat.
 */
public struct ForumHostRow {
    /**
     * The room's object id.
     */
    public var forum: String
    /**
     * The hosting Group's object id.
     */
    public var group: String
    /**
     * The hosting Group's folded displayName ("" when its profile was never set).
     */
    public var groupName: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The room's object id.
         */forum: String, 
        /**
         * The hosting Group's object id.
         */group: String, 
        /**
         * The hosting Group's folded displayName ("" when its profile was never set).
         */groupName: String) {
        self.forum = forum
        self.group = group
        self.groupName = groupName
    }
}



extension ForumHostRow: Equatable, Hashable {
    public static func ==(lhs: ForumHostRow, rhs: ForumHostRow) -> Bool {
        if lhs.forum != rhs.forum {
            return false
        }
        if lhs.group != rhs.group {
            return false
        }
        if lhs.groupName != rhs.groupName {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(forum)
        hasher.combine(group)
        hasher.combine(groupName)
    }
}


