/**
 * One row of the LIFE ▸ GROUPS listing: a Group identity record, folded — the
 * whole list in one FFI call, no per-row `group_view` round trips.
 */
public struct GroupListRow {
    public var id: String
    /**
     * The folded displayName; "" when the profile was never set (the UI derives
     * a label from the roster then, never from id hex).
     */
    public var name: String
    public var shape: String
    /**
     * MLS roster size — membership's one source (the ratchet tree).
     */
    public var members: UInt32
    /**
     * How many rooms this group hosts (the folded forum-edge count).
     */
    public var forums: UInt32
    /**
     * The avatar's still + colour slots (clip → photo → colour, like a connection).
     */
    public var photo: String
    public var photoMime: String
    public var avatarColor: String
    public var canSync: Bool
    /**
     * TRUE for a Space — a body you belong to; FALSE for an identity RECORD, the
     * card this device keeps for one contact. Decided by the CORE (`group_rows`),
     * never re-derived here or in the app: the two share the same object
     * machinery, and every consumer that guessed got it wrong differently.
     */
    public var isSpace: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: String, 
        /**
         * The folded displayName; "" when the profile was never set (the UI derives
         * a label from the roster then, never from id hex).
         */name: String, shape: String, 
        /**
         * MLS roster size — membership's one source (the ratchet tree).
         */members: UInt32, 
        /**
         * How many rooms this group hosts (the folded forum-edge count).
         */forums: UInt32, 
        /**
         * The avatar's still + colour slots (clip → photo → colour, like a connection).
         */photo: String, photoMime: String, avatarColor: String, canSync: Bool, 
        /**
         * TRUE for a Space — a body you belong to; FALSE for an identity RECORD, the
         * card this device keeps for one contact. Decided by the CORE (`group_rows`),
         * never re-derived here or in the app: the two share the same object
         * machinery, and every consumer that guessed got it wrong differently.
         */isSpace: Bool) {
        self.id = id
        self.name = name
        self.shape = shape
        self.members = members
        self.forums = forums
        self.photo = photo
        self.photoMime = photoMime
        self.avatarColor = avatarColor
        self.canSync = canSync
        self.isSpace = isSpace
    }
}



extension GroupListRow: Equatable, Hashable {
    public static func ==(lhs: GroupListRow, rhs: GroupListRow) -> Bool {
        if lhs.id != rhs.id {
            return false
        }
        if lhs.name != rhs.name {
            return false
        }
        if lhs.shape != rhs.shape {
            return false
        }
        if lhs.members != rhs.members {
            return false
        }
        if lhs.forums != rhs.forums {
            return false
        }
        if lhs.photo != rhs.photo {
            return false
        }
        if lhs.photoMime != rhs.photoMime {
            return false
        }
        if lhs.avatarColor != rhs.avatarColor {
            return false
        }
        if lhs.canSync != rhs.canSync {
            return false
        }
        if lhs.isSpace != rhs.isSpace {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(id)
        hasher.combine(name)
        hasher.combine(shape)
        hasher.combine(members)
        hasher.combine(forums)
        hasher.combine(photo)
        hasher.combine(photoMime)
        hasher.combine(avatarColor)
        hasher.combine(canSync)
        hasher.combine(isSpace)
    }
}


