/**
 * The folded Group read-model — the reusable identity record the directory UI
 * binds to. `presence`/`can_sync` say whether this contact is reachable over MLS.
 */
public struct GroupRow {
    public var displayName: String
    public var shape: String
    public var presence: String
    public var canSync: Bool
    public var org: String
    public var title: String
    public var note: String
    public var photo: String
    public var emails: [LabeledRow]
    public var phones: [LabeledRow]
    public var urls: [LabeledRow]
    public var tags: [String]
    public var roles: [GroupRoleRow]
    public var credentials: [CredentialRow]
    /**
     * Group↔Group edges (this group's half) — a chapter lists its federation here.
     */
    public var affiliations: [AffiliationRow]
    /**
     * The appointments this body has made. An office with no row is VACANT.
     */
    public var offices: [OfficeRow]
    /**
     * The avatar slots, same shape as `ProfileCard` — an identity record renders
     * its face the same way a connection's does (clip → photo → colour).
     */
    public var photoMime: String
    public var clip: String
    public var clipMime: String
    public var capturedAt: UInt64
    public var avatarColor: String
    /**
     * The COVER banner (base64 + mime, "" = none): a still, an animated gif, or a
     * short mp4 — the group page's wall, beside the avatar's face.
     */
    public var cover: String
    public var coverMime: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(displayName: String, shape: String, presence: String, canSync: Bool, org: String, title: String, note: String, photo: String, emails: [LabeledRow], phones: [LabeledRow], urls: [LabeledRow], tags: [String], roles: [GroupRoleRow], credentials: [CredentialRow], 
        /**
         * Group↔Group edges (this group's half) — a chapter lists its federation here.
         */affiliations: [AffiliationRow], 
        /**
         * The appointments this body has made. An office with no row is VACANT.
         */offices: [OfficeRow], 
        /**
         * The avatar slots, same shape as `ProfileCard` — an identity record renders
         * its face the same way a connection's does (clip → photo → colour).
         */photoMime: String, clip: String, clipMime: String, capturedAt: UInt64, avatarColor: String, 
        /**
         * The COVER banner (base64 + mime, "" = none): a still, an animated gif, or a
         * short mp4 — the group page's wall, beside the avatar's face.
         */cover: String, coverMime: String) {
        self.displayName = displayName
        self.shape = shape
        self.presence = presence
        self.canSync = canSync
        self.org = org
        self.title = title
        self.note = note
        self.photo = photo
        self.emails = emails
        self.phones = phones
        self.urls = urls
        self.tags = tags
        self.roles = roles
        self.credentials = credentials
        self.affiliations = affiliations
        self.offices = offices
        self.photoMime = photoMime
        self.clip = clip
        self.clipMime = clipMime
        self.capturedAt = capturedAt
        self.avatarColor = avatarColor
        self.cover = cover
        self.coverMime = coverMime
    }
}



