/**
 * One field a kind requires to come into existence.
 *
 * The TYPE declares these; the UI is built from them. Before this the UI decided, in a
 * hand-written switch, and the reducers' `req_text`/`req_int` calls decided separately —
 * two statements of one fact, and they had drifted in four places at once.
 */
public struct MintFieldRow {
    public var key: MintKey
    /**
     * The field's name as the person filling it reads it.
     */
    public var label: String
    public var input: MintInput
    /**
     * Empty unless `input == Choice`.
     */
    public var choices: [String]
    /**
     * The mint cannot commit without it.
     */
    public var required: Bool
    /**
     * The field is SHOWN but does not yet persist — see `Carriage::Deferred`. The UI must
     * present it honestly rather than as a live control that saves.
     */
    public var deferred: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(key: MintKey, 
        /**
         * The field's name as the person filling it reads it.
         */label: String, input: MintInput, 
        /**
         * Empty unless `input == Choice`.
         */choices: [String], 
        /**
         * The mint cannot commit without it.
         */required: Bool, 
        /**
         * The field is SHOWN but does not yet persist — see `Carriage::Deferred`. The UI must
         * present it honestly rather than as a live control that saves.
         */deferred: Bool) {
        self.key = key
        self.label = label
        self.input = input
        self.choices = choices
        self.required = required
        self.deferred = deferred
    }
}



extension MintFieldRow: Equatable, Hashable {
    public static func ==(lhs: MintFieldRow, rhs: MintFieldRow) -> Bool {
        if lhs.key != rhs.key {
            return false
        }
        if lhs.label != rhs.label {
            return false
        }
        if lhs.input != rhs.input {
            return false
        }
        if lhs.choices != rhs.choices {
            return false
        }
        if lhs.required != rhs.required {
            return false
        }
        if lhs.deferred != rhs.deferred {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(key)
        hasher.combine(label)
        hasher.combine(input)
        hasher.combine(choices)
        hasher.combine(required)
        hasher.combine(deferred)
    }
}


