    public static func ==(lhs: PostRow, rhs: PostRow) -> Bool {
        if lhs.id != rhs.id {
            return false
        }
        if lhs.title != rhs.title {
            return false
        }
        if lhs.body != rhs.body {
            return false
        }
        if lhs.icon != rhs.icon {
