        }
        if lhs.retracted != rhs.retracted {
            return false
        }
        if lhs.reactions != rhs.reactions {
            return false
        }
        if lhs.comments != rhs.comments {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(id)
