    public var verified: Bool
    /**
     * Epoch ms the door told the holder they were let in; 0 = not admitted.
     * The buyer is not a member of the Event group, so this receipt — carried on
     * the pairwise channel — is the ONLY way their device can know.
     */
    public var admittedMs: Int64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(ticket: String, listing: String, core: String, sig: String, qr: String, title: String, startMs: Int64, verified: Bool, 
        /**
         * Epoch ms the door told the holder they were let in; 0 = not admitted.
         * The buyer is not a member of the Event group, so this receipt — carried on
         * the pairwise channel — is the ONLY way their device can know.
         */admittedMs: Int64) {
        self.ticket = ticket
        self.listing = listing
        self.core = core
        self.sig = sig
        self.qr = qr
        self.title = title
        self.startMs = startMs
        self.verified = verified
        self.admittedMs = admittedMs
    }
}



