    public static func ==(lhs: WalletTicketRow, rhs: WalletTicketRow) -> Bool {
        if lhs.ticket != rhs.ticket {
            return false
        }
        if lhs.listing != rhs.listing {
            return false
        }
        if lhs.core != rhs.core {
            return false
        }
        if lhs.sig != rhs.sig {
            return false
        }
        if lhs.qr != rhs.qr {
            return false
        }
        if lhs.title != rhs.title {
            return false
        }
        if lhs.startMs != rhs.startMs {
            return false
        }
        if lhs.verified != rhs.verified {
            return false
        }
        if lhs.admittedMs != rhs.admittedMs {
            return false
        }
        return true
    }

